import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private Map<String, List<String>> commentsMap;

    @InjectMocks
    private CommentsConfiguration commentsConfiguration;

    @Before
    public void setup() {
        MockitoAnnotations.initMocks(this);
    }

    @Test
    public void constructorShouldCreateNewInstance() {
        assertNotNull(commentsConfiguration);
    }

    @Test
    public void constructorWithCommentsMapShouldInitializeComments() {
        when(commentsMap.size()).thenReturn(1);
        commentsConfiguration = new CommentsConfiguration(commentsMap);
        assertNotNull(commentsConfiguration.getComment("key"));
